.news-detail{--news-muted:#60718e;--news-border:#e2e8f0;color:#16233d;max-width:1440px;margin:auto;width:100%;font-size:14px;line-height:1.55}.news-detail [x-cloak]{display:none!important}.news-back{display:flex;align-items:center;gap:10px;color:var(--news-muted);font-size:13px;margin:0 0 14px}.news-back span{color:#bbc5d4}.news-icon{width:20px;height:20px;flex-shrink:0;color:#2563eb}.news-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:22px}.news-heading>div{min-width:0;max-width:920px}.news-heading>a{flex-shrink:0;margin-top:28px}.news-heading h1{font-size:clamp(23px,2.1vw,32px);font-weight:750;line-height:1.25;letter-spacing:-.035em;margin:6px 0 13px;overflow-wrap:anywhere}.news-eyebrow{font-size:13px;color:#526986}.news-muted{color:var(--news-muted);margin:9px 0}.news-dot{margin:0 8px}.news-badges{display:flex;flex-wrap:wrap;gap:7px;margin:14px 0}.news-caption{color:var(--news-muted);font-size:12px;margin:9px 0;line-height:1.5}.news-navigation{overflow-x:auto;border-bottom:1px solid var(--news-border);margin:16px 0}.news-navigation .fi-tabs{justify-content:flex-start;flex-wrap:nowrap}.news-layout{display:grid;grid-template-columns:minmax(0,2.15fr) minmax(275px,1fr);gap:20px;align-items:start;margin-bottom:22px}.news-main,.news-aside{display:grid;gap:18px;min-width:0}.news-detail .fi-section{box-shadow:none;border:1px solid var(--news-border);border-radius:10px}.news-detail .fi-section-header{padding:16px 19px}.news-detail .fi-section-content{padding:0 19px 19px}.news-detail .fi-section-header-heading{font-size:15px;font-weight:700}.news-summary{font-size:16px;line-height:1.6;margin:0}.news-why{background:#eff6ff;border:1px solid #dbeafe;border-radius:8px;padding:14px 16px;margin-top:16px}.news-why h3{display:flex;gap:8px;align-items:center;font-weight:650;color:#1d4ed8;margin-bottom:8px}.news-why ul{padding-left:18px;list-style:disc}.news-why li{margin:4px 0}.news-fact-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.news-fact{border:1px solid var(--news-border);border-radius:8px;padding:14px;display:flex;flex-direction:column;align-items:flex-start;min-width:0}.news-fact-title{display:flex;gap:9px;align-items:center;font-weight:650;margin-bottom:10px}.news-fact-value{font-size:23px;font-weight:700;line-height:1.3;margin-bottom:8px;overflow-wrap:anywhere}.news-fact-text{font-size:13px;line-height:1.6;margin:8px 0}.news-evidence{width:100%;margin-top:auto;font-size:13px}.news-detail summary{cursor:pointer}.news-evidence summary{border:1px solid #dbeafe;color:#2563eb;text-align:center;border-radius:5px;padding:5px 8px}.news-detail blockquote{margin-top:10px;padding:10px;border-left:3px solid #fbbf24;line-height:1.7}.news-detail mark{background:#fef3c7;color:#503a16;box-decoration-break:clone}.news-more{margin-top:14px}.news-intelligence{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:15px}.news-intelligence>div+div{border-left:1px solid var(--news-border);padding-left:15px}.news-intelligence h3{font-size:13px;font-weight:650;color:#526986}.news-intelligence .fi-badge{white-space:normal;text-align:left;overflow-wrap:anywhere}.news-asset{padding:7px 0;border-bottom:1px solid var(--news-border)}.news-asset summary{display:flex;justify-content:space-between;gap:7px}.news-article{max-width:74ch;white-space:pre-wrap;line-height:1.75;overflow-wrap:anywhere}.news-article p+p{margin-top:1em}.news-excerpt{background:#f8fafc;padding:16px;border-radius:7px;border:1px solid var(--news-border);color:#526986}.news-source-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:14px}.news-properties{display:grid;grid-template-columns:minmax(90px,.9fr) minmax(0,1.25fr);gap:13px 12px;font-size:13px}.news-properties dt{color:var(--news-muted)}.news-properties dd{overflow-wrap:anywhere}.news-empty{background:#fff9ed;border-radius:7px;padding:13px;color:#775623}.news-detail pre{max-height:650px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.news-detail table{font-size:12px}.news-mini-price{font-size:25px;font-weight:700}.news-review select,.news-review textarea{color:inherit;background:transparent}.dark .news-detail{color:#e2e8f0;--news-muted:#a1b1cb;--news-border:#334155}.dark .news-why{background:#172b47;border-color:#284366}.dark .news-why h3{color:#93c5fd}.dark .news-excerpt{background:#172033;color:#cbd5e1}.dark .news-empty{background:#332b1a;color:#fcd891}
